Here is a simple and efficient C++ program to calculate Power and Resistance based on user input for Voltage and Current.

### The Code

```cpp
#include <iostream>
#include <iomanip> // Used for formatting decimal places

using namespace std;

int main() {
    // Variable declarations
    double voltage, current, power, resistance;

    cout << "--- Electrical Calculator ---" << endl;

    // Taking input from the user
    cout << "Enter Voltage (Volts): ";
    cin >> voltage;

    cout << "Enter Current (Amperes): ";
    cin >> current;

    // Input Validation: Check if current is zero to avoid division by zero
    if (current == 0) {
        cout << "\nError: Current cannot be zero. Resistance would be infinite." << endl;
    } else {
        // Calculation
        // Formula for Power: P = V * I
        power = voltage * current;

        // Formula for Resistance (Ohm's Law): R = V / I
        resistance = voltage / current;

        // Setting output to 2 decimal places for cleanliness
        cout << fixed << setprecision(2);

        cout << "\n--- Results ---" << endl;
        cout << "Power     : " << power << " Watts" << endl;
        cout << "Resistance: " << resistance << " Ohms" << endl;
    }

    return 0;
}
```

